// ❌ Breaks under StrictMode: subscription leaks and doubled state
const store = new EventStore();   // module-level mutable state

function Buggy() {
  const [events, setEvents] = useState([]);

  useEffect(() => {
    store.on('event', handler);                    // setup
    // NO cleanup -> StrictMode's remount subscribes TWICE
    setEvents((e) => [...e, 'mounted']);           // runs twice -> two entries
  }, []);

  return <ul>{events.map((e, i) => <li key={i}>{e}</li>)}</ul>;// }

// ✅ Fixed: cleanup reverses setup; setup is idempotent
function Fixed() {
  const [events, setEvents] = useState([]);

  useEffect(() => {
    const handler = (payload) => setEvents((e) => [...e, payload]);
    store.on('event', handler);
    setEvents((e) => [...e, 'mounted']);

    return () => store.off('event', handler);      // undo subscription
  }, []);

  return <ul>{events.map((e, i) => <li key={i}>{e}</li>)}</ul>;// }

// Setup/cleanup symmetric — double-invocation is now harmless.

